from __future__ import annotations

import csv
import json
import math
import re
from calendar import monthrange
from collections import defaultdict
from datetime import date, timedelta
from itertools import product
from pathlib import Path


DATASET_DIR = Path("/app/dataset")
EMPLOYEES_CSV = DATASET_DIR / "employees.csv"
TASKS_CSV = DATASET_DIR / "tasks.csv"
TIMESHEET_CSV = DATASET_DIR / "timesheet.csv"


def _read_csv(path: Path) -> list[dict[str, str]]:
    with path.open(newline="", encoding="utf-8") as handle:
        return list(csv.DictReader(handle))


def _fix_date(raw: str) -> date:
    year, month, day = map(int, raw.split("-"))
    return date(year, month, min(day, monthrange(year, month)[1]))


def _parse_task_ids(raw: str) -> list[int]:
    return [int(token) for token in re.findall(r"\d+", raw)]


def _hamming_distance(left: str, right: str) -> int:
    if len(left) != len(right):
        return 10**9
    return sum(a != b for a, b in zip(left, right))


def _period_start(day: date, weekday: int) -> date:
    current = day.replace(day=1)
    while current.weekday() != weekday:
        current += timedelta(days=1)
    if day >= current:
        return current

    previous_month_last_day = day.replace(day=1) - timedelta(days=1)
    current = previous_month_last_day.replace(day=1)
    while current.weekday() != weekday:
        current += timedelta(days=1)
    return current


def answer() -> dict[str, list[int]]:
    employees = _read_csv(EMPLOYEES_CSV)
    tasks = _read_csv(TASKS_CSV)
    timesheet = _read_csv(TIMESHEET_CSV)

    employee_rows = {row["PESEL"]: row for row in employees}
    hourly_rate = {pesel: float(row["hourly_rate"]) for pesel, row in employee_rows.items()}
    valid_pesels = sorted(employee_rows)

    task_pay = {int(row["task_id"]): int(row["pay_per_completion"]) for row in tasks}
    task_ids = sorted(task_pay)
    task_ids_as_text = {task_id: str(task_id) for task_id in task_ids}

    valid_dates = []
    for row in timesheet:
        try:
            valid_dates.append(date.fromisoformat(row["date"]))
        except ValueError:
            valid_dates.append(_fix_date(row["date"]))
    pay_cycle_weekday = min(valid_dates).weekday()

    def mapped_pesel(raw_pesel: str) -> str:
        if raw_pesel in employee_rows:
            return raw_pesel
        return min(valid_pesels, key=lambda pesel: (_hamming_distance(raw_pesel, pesel), pesel))

    def unknown_task_pay_options(task_id: int) -> list[int]:
        task_text = str(task_id)
        distances = sorted(
            (_hamming_distance(task_text, task_ids_as_text[candidate]), candidate) for candidate in task_ids
        )
        best_distance = distances[0][0]
        return sorted({task_pay[candidate] for distance, candidate in distances if distance == best_distance})

    # Drop exact duplicate logical rows. Different `id` values are not enough to make
    # a row trustworthy when every other business field is identical.
    cleaned_rows: list[dict[str, object]] = []
    seen_rows: set[tuple[str, str, str, str, str, str, str]] = set()
    for row in timesheet:
        dedupe_key = (
            row["date"],
            row["hours_worked"],
            row["performed_tasks"],
            row["employee_id"],
            row["facility_id"],
            row["salary_amount"],
            row["bonus"],
        )
        if dedupe_key in seen_rows:
            continue
        seen_rows.add(dedupe_key)
        fixed_day = _fix_date(row["date"])
        cleaned_rows.append(
            {
                **row,
                "fixed_date": fixed_day,
                "period_start": _period_start(fixed_day, pay_cycle_weekday),
                "mapped_pesel": mapped_pesel(row["employee_id"]),
            }
        )

    period_starts = sorted({row["period_start"] for row in cleaned_rows})

    # Base pay is reconstructed from the cumulative salary ledger. For corrupted PESELs,
    # the running total sometimes fails to reset between months, so we compute the period
    # total from period-end balances per original employee_id and then map it to the
    # corrected PESEL.
    base_salary_by_employee_period: defaultdict[tuple[str, date], float] = defaultdict(float)
    rows_by_original_employee: defaultdict[str, list[dict[str, object]]] = defaultdict(list)
    for row in cleaned_rows:
        rows_by_original_employee[str(row["employee_id"])].append(row)

    for original_employee_id, original_rows in rows_by_original_employee.items():
        corrected_pesel = mapped_pesel(original_employee_id)
        salary_by_period: defaultdict[date, list[float]] = defaultdict(list)
        for row in original_rows:
            salary_by_period[row["period_start"]].append(float(row["salary_amount"]))

        previous_period_end: float | None = None
        for period in sorted(salary_by_period):
            period_values = salary_by_period[period]
            period_start_balance = min(period_values)
            period_end_balance = max(period_values)
            if previous_period_end is None:
                period_base = period_end_balance
            elif period_start_balance >= previous_period_end:
                period_base = period_end_balance - previous_period_end
            else:
                period_base = period_end_balance

            base_salary_by_employee_period[(corrected_pesel, period)] += period_base
            previous_period_end = period_end_balance

    # Bonuses are trusted only when they can be derived from the task catalog after
    # conservative repairs. If the task payout is still ambiguous, the bonus is excluded.
    bonus_by_employee_period: defaultdict[tuple[str, date], int] = defaultdict(int)
    possible_bonus_total_cache: dict[tuple[tuple[int, ...], ...], set[int]] = {}
    for row in cleaned_rows:
        task_list = _parse_task_ids(str(row["performed_tasks"]))
        if not task_list:
            continue

        pay_options: list[list[int]] = []
        for task_id in task_list:
            if task_id in task_pay:
                pay_options.append([task_pay[task_id]])
            else:
                pay_options.append(unknown_task_pay_options(task_id))

        cache_key = tuple(tuple(options) for options in pay_options)
        if cache_key not in possible_bonus_total_cache:
            possible_bonus_total_cache[cache_key] = {sum(combo) for combo in product(*pay_options)}

        possible_bonus_totals = possible_bonus_total_cache[cache_key]
        if len(possible_bonus_totals) != 1:
            continue

        bonus_by_employee_period[(str(row["mapped_pesel"]), row["period_start"])] += next(
            iter(possible_bonus_totals)
        )

    result: dict[str, list[int]] = {}
    for pesel in valid_pesels:
        salaries: list[int] = []
        for period in period_starts:
            total = (
                base_salary_by_employee_period.get((pesel, period), 0.0)
                + bonus_by_employee_period.get((pesel, period), 0)
            )
            salaries.append(int(math.floor(total + 0.5)))
        result[pesel] = salaries

    return result


if __name__ == "__main__":
    with open("/app/answer.json", "w", encoding="utf-8") as handle:
        json.dump(answer(), handle, default=list)
